# area: typeddict
# hypothesis: Required and NotRequired keys decide which dict literals type-check, a NotRequired key needs an 'in' guard before it is read, and Unpack kwargs reject unknown keys and wrong value types.
from typing import NotRequired, Required, TypedDict, Unpack, reveal_type


class Base(TypedDict, total=False):
    color: str


class Item(TypedDict):
    name: Required[str]
    price: NotRequired[float]
    tags: list[str]


class Stock(TypedDict):
    count: int


def make(**kwargs: Unpack[Item]) -> Item:
    return kwargs


def total_cost(item: Item) -> float:
    if 'price' in item:
        reveal_type(item['price'])
        return item['price']
    return 0.0


item: Item = {'name': 'pen', 'tags': ['blue']}
item.update({'price': 1.5})
reveal_type(item.get('price'))
bad: Item = {'tags': []}  # expect-error: missing required name
tint: Base = {}
stock: Stock = {'count': 3}
print(total_cost(item), tint.get('color', 'none'), stock['count'] + 1)
print(make(name='pen', tags=[]))
print(make(name='cup', tags=[], weight=2))  # expect-error: unknown key
print(make(name=3, tags=[]))  # expect-error: wrong value type
